sealed class WalletException(message: String): kotlin.Exception(message) {
        
        class CryptoException(message: String) : WalletException(message)
        
        class NetworkException(message: String) : WalletException(message)
        
        class StorageException(message: String) : WalletException(message)
        
        class InvalidInput(message: String) : WalletException(message)
        
        class InsufficientBalance(message: String) : WalletException(message)
        
        class WalletLocked(message: String) : WalletException(message)
        
        class NotInitialized(message: String) : WalletException(message)
        
        class SyncInProgress(message: String) : WalletException(message)
        
        class RuntimeException(message: String) : WalletException(message)
        
        class BroadcastFailed(message: String) : WalletException(message)
        
        class InvalidAnchor(message: String) : WalletException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WalletException> {
        override fun lift(error_buf: RustBuffer.ByValue): WalletException = FfiConverterTypeWalletError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeWalletError : FfiConverterRustBuffer<WalletException> {
    override fun read(buf: ByteBuffer): WalletException {
        
            return when(buf.getInt()) {
            1 -> WalletException.CryptoException(FfiConverterString.read(buf))
            2 -> WalletException.NetworkException(FfiConverterString.read(buf))
            3 -> WalletException.StorageException(FfiConverterString.read(buf))
            4 -> WalletException.InvalidInput(FfiConverterString.read(buf))
            5 -> WalletException.InsufficientBalance(FfiConverterString.read(buf))
            6 -> WalletException.WalletLocked(FfiConverterString.read(buf))
            7 -> WalletException.NotInitialized(FfiConverterString.read(buf))
            8 -> WalletException.SyncInProgress(FfiConverterString.read(buf))
            9 -> WalletException.RuntimeException(FfiConverterString.read(buf))
            10 -> WalletException.BroadcastFailed(FfiConverterString.read(buf))
            11 -> WalletException.InvalidAnchor(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: WalletException): ULong {
        return 4UL
    }

    override fun write(value: WalletException, buf: ByteBuffer) {
        when(value) {
            is WalletException.CryptoException -> {
                buf.putInt(1)
                Unit
            }
            is WalletException.NetworkException -> {
                buf.putInt(2)
                Unit
            }
            is WalletException.StorageException -> {
                buf.putInt(3)
                Unit
            }
            is WalletException.InvalidInput -> {
                buf.putInt(4)
                Unit
            }
            is WalletException.InsufficientBalance -> {
                buf.putInt(5)
                Unit
            }
            is WalletException.WalletLocked -> {
                buf.putInt(6)
                Unit
            }
            is WalletException.NotInitialized -> {
                buf.putInt(7)
                Unit
            }
            is WalletException.SyncInProgress -> {
                buf.putInt(8)
                Unit
            }
            is WalletException.RuntimeException -> {
                buf.putInt(9)
                Unit
            }
            is WalletException.BroadcastFailed -> {
                buf.putInt(10)
                Unit
            }
            is WalletException.InvalidAnchor -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





